  "recipeIngredient": [
    "4 skinless, boneless chicken breast halves",
    "salt and freshly ground black pepper to taste",
    "2 large eggs",
    "1 cup panko bread crumbs, or more as needed",
    "0.75 cup grated Parmesan cheese, divided",
